<?php
require 'init.php'; require_student(); require 'db.php';
$statuses=['Pending','Offered','Rejected','Offer Accepted','Offer Declined'];
$stmt=$pdo->prepare('SELECT status, COUNT(*) AS total FROM applications WHERE user_id=? GROUP BY status'); $stmt->execute([$_SESSION['user_id']]); $counts=$stmt->fetchAll(PDO::FETCH_KEY_PAIR); $values=array_map(fn($s)=>(int)($counts[$s]??0),$statuses);
$stmt=$pdo->prepare('SELECT application_date, COUNT(*) AS total FROM applications WHERE user_id=? AND application_date BETWEEN ? AND ? GROUP BY application_date'); $today=new DateTimeImmutable('today'); $start=$today->modify('-27 days'); $stmt->execute([$_SESSION['user_id'],$start->format('Y-m-d'),$today->format('Y-m-d')]); $daily=$stmt->fetchAll(PDO::FETCH_KEY_PAIR); $weeks=[0,0,0,0]; $labels=[]; for($i=0;$i<28;$i++){ $d=$start->modify("+$i days"); $w=intdiv($i,7); $weeks[$w]+=(int)($daily[$d->format('Y-m-d')]??0); if($i%7===0) $labels[]=$d->format('d M').' – '.$d->modify('+6 days')->format('d M'); }
$title='Dashboard'; require 'header.php'; ?>
<p class="eyebrow">STUDENT PORTAL</p><h1>Internship overview</h1><p class="muted">Welcome, <?= e($_SESSION['name']) ?>. Find your placement and monitor your progress.</p>
<section class="row row-cols-2 row-cols-lg-3 g-3 my-4"><?php foreach(array_merge(['Total applications'=>array_sum($values)],array_combine($statuses,$values)) as $label=>$count): ?><div class="col"><article class="card panel stat h-100"><p><?= e($label) ?></p><strong><?= $count ?></strong></article></div><?php endforeach; ?></section>
<div class="row g-3"><div class="col-lg-6"><section class="card panel h-100"><h2>Application Status Overview</h2><p class="muted">All your applications by current status.</p><?php if(array_sum($values)): ?><div style="height:280px"><canvas id="statusChart"></canvas></div><?php else: ?><p>No applications yet. <a href="companies.php">Find an internship</a> to get started.</p><?php endif; ?></section></div><div class="col-lg-6"><section class="card panel h-100"><h2>Application Progress</h2><p class="muted">Applications submitted over the last 28 days.</p><div style="height:280px"><canvas id="progressChart"></canvas></div></section></div></div>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.8/dist/chart.umd.min.js"></script><script>
if(typeof Chart !== 'undefined') { Chart.defaults.color='#cbd5e1'; const status=document.getElementById('statusChart'); if(status) new Chart(status,{type:'doughnut',data:{labels:<?= json_encode($statuses) ?>,datasets:[{data:<?= json_encode($values) ?>,backgroundColor:['#fbbf24','#60a5fa','#f87171','#4ade80','#94a3b8']}]},options:{maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}}}); new Chart(document.getElementById('progressChart'),{type:'bar',data:{labels:<?= json_encode($labels) ?>,datasets:[{label:'Applications submitted',data:<?= json_encode($weeks) ?>,backgroundColor:'#a5b4fc'}]},options:{maintainAspectRatio:false,scales:{y:{beginAtZero:true,ticks:{precision:0}}},plugins:{legend:{display:false}}}}); } else { document.querySelectorAll('canvas').forEach(c=>c.replaceWith(document.createTextNode('Chart library unavailable. Check internet connection.'))); }
</script><?php require 'footer.php'; ?>
